import { PureComponent } from 'react'
import AppFaqStyleWrapper from './style'
import { Collapse } from 'antd'
import IntlMessages from '../../../components/utility/intlMessages'
import { FAQS, TERMS_CONDITIONS } from '../constants'

export class ReferralTermsAndCondition extends PureComponent {
  render () {
    const { Panel } = Collapse

    return (
      <AppFaqStyleWrapper>
        <div>
          <ul className='terms-and-condition-points'>
            {
              TERMS_CONDITIONS.map((val, ind) => (
                (
                  <li className='point-list' key={ind}>
                    <IntlMessages id={val} />
                  </li>
                )
              ))
            }
          </ul>
          <hr className='break-point' />
          <h3 className='faq-heading mb-25 mt-15'><IntlMessages id='Pertanyaan Sering Diajukan' /></h3>
          <Collapse accordion>{
            FAQS.map((val, ind) => {
              return (
                <Panel header={<IntlMessages id={val['header']} />} key={ind}>
                  {
                    Array.isArray(val['description'])
                      ? (
                        <ol className='faq-points'>
                          {
                            val['description'].map((value, index) => (
                              <li className='point-list' key={index}>
                                <IntlMessages id={value} />
                              </li>
                            )
                            )
                          }
                        </ol>
                      )
                      : (
                        <p className='panel-description'>
                          <IntlMessages id={val['description']} />
                        </p>
                      )
                  }
                </Panel>
              )
            })
          }
          </Collapse>
        </div>
      </AppFaqStyleWrapper >
    )
  }
}

export default ReferralTermsAndCondition
